        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if nx < 0 or ny < 0 or nx >= w or ny >= h or (nx, ny) in os:
                continue
            v = -abs(tx - nx) - abs(ty - ny)
            if (nx, ny) == (ox, oy):
                v += 1
            if v > bestv:
                bestv = v
                best = (dx, dy)
    else:
        dx = 1 if ox < sx else -1 if ox > sx else 0
        dy = 1 if oy < sy else -1 if oy > sy else 0
        cand = [(dx, 0), (0, dy), (dx, dy), (0, 0)]
        for dx, dy in cand:
            nx, ny = sx + dx, sy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in os:
                return [dx, dy]
    return [best[0], best[1]]

